function assign(row){draft.description=row?.description||"";draft.details=row?.details||"";draft.exams=(row?.registered_exams||[]).map(item=>({...item,description:item.description||props.exams.find(exam=>exam.id===item.examId)?.description||`Examen ${item.examId}`}))}function snapshot(){return JSON.stringify(values.value)}function syncDirty(){dirty.value=!initializing.value&&snapshot()!==original.value}function clearGeneralError(){errorMessage.value=""}function handleDescriptionInput(){clearGeneralError();syncDirty()}function handleDetailsInput(){clearGeneralError();syncDirty()}async function show(){await dialog.value?.open();await nextTick();original.value=snapshot();dirty.value=false;initializing.value=false;firstInput.value?.focus()}async function openCreate(){initializing.value=true;mode.value="create";current.value=null;assign(null);attempted.value=false;errorMessage.value="";search.value="";await show()}async function openEdit(row){initializing.value=true;mode.value="edit";current.value=row;assign(row);attempted.value=false;errorMessage.value="";search.value="";await show()}function openDetail(exam){detailDialog.value?.open(exam)}async function add(exam){draft.exams.push({examId:exam.id,description:exam.description,abbreviation:exam.abbreviation});syncDirty();keyboardId.value=null;keyboardOriginal.value=[];await nextTick();revealRow(exam.id)}function remove(index){draft.exams.splice(index,1);syncDirty();keyboardId.value=null}function move(index,delta){const target=index+delta;if(target<0||target>=draft.exams.length)return;const[row]=draft.exams.splice(index,1);draft.exams.splice(target,0,row);syncDirty();focusRow(row.examId)}function selectKeyboard(id){if(keyboardId.value!==id){keyboardId.value=id;keyboardOriginal.value=draft.exams.map(item=>item.examId)}}function activateKeyboardSelection(id,event){event?.preventDefault?.();event?.stopPropagation?.();if(keyboardId.value===id)return;keyboardId.value=null;selectKeyboard(id);focusRow(id)}function revealRow(id){c